    {
      "card_ids": ["C12"],
      "claim": "Vilazodone, an indole-containing drug with a basic amine side chain, has an absolute oral bioavailability of 72% in healthy volunteers in the fed state, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Flavoxate showed near-complete oral bioavailability close to 100% in healthy male volunteers based on oral versus intravenous comparison, supporting high F.",
