      "claim": "Sulthiame was reported to have complete oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Mizolastine has an absolute oral bioavailability of 65% for tablets in healthy young volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Bepridil has a calculated oral availability of 62% from single-dose oral studies in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Ilomastat was reported not to show good oral bioavailability, providing a contradictory data point, but it is a hydroxamic acid MMP inhibitor rather than a triptan-like indole derivative.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a triptan-like indole with a basic dimethylaminoethyl side chain and a sulfonamide substituent. The highly transferable experimental evidence overwhelmingly shows oral bioavailability values well above the 20% threshold, typically 60-100%, with only one chemically distinct low-bioavailability outlier. Therefore F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule is included in the provided evidence.",
    "The single contradictory low-bioavailability analogue, ilomastat, is structurally distinct and may not reflect the absorption and first-pass properties of the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

